const USER=process.env.WP_USER.trim(),PASS=process.env.WP_APP_PASS.trim();
const AUTH='Basic '+Buffer.from(USER+':'+PASS).toString('base64');
const BASE='https://dev.avesa.lt/wp-json/code-snippets/v1/snippets';
const TOK=process.env.GH_TOKEN;
process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const D='', A='';
async function putResult(n,o){
  const url='https://api.github.com/repos/raimis079-creator/petshop-bridge/contents/screenshots/'+n;
  let sha;const g=await fetch(url,{headers:{Authorization:'Bearer '+TOK}});
  if(g.status===200) sha=(await g.json()).sha;
  const b={message:'r '+n,content:Buffer.from(JSON.stringify(o,null,1)).toString('base64')}; if(sha)b.sha=sha;
  const r=await fetch(url,{method:'PUT',headers:{Authorization:'Bearer '+TOK,'Content-Type':'application/json'},body:JSON.stringify(b)});
  console.log('putResult',n,r.status);
}
async function putFile(p,buf,m){
  const url='https://api.github.com/repos/raimis079-creator/petshop-bridge/contents/'+p;
  let sha;const g=await fetch(url,{headers:{Authorization:'Bearer '+TOK}});
  if(g.status===200) sha=(await g.json()).sha;
  const b={message:m,content:buf.toString('base64')}; if(sha)b.sha=sha;
  const r=await fetch(url,{method:'PUT',headers:{Authorization:'Bearer '+TOK,'Content-Type':'application/json'},body:JSON.stringify(b)});
  console.log('putFile',p,r.status);
}
async function snip(name,code){
  const r=await fetch(BASE,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name,code:Buffer.from(code,'base64').toString('utf8'),scope:'global',active:true,priority:11})});
  return (await r.json()).id;
}
const out={version:'S675-V1',errors:[]};
// diegimas
try{
  const idD=await snip('TEMP Katalogo Diegejas v10 (S675)', D);
  await new Promise(x=>setTimeout(x,3000));
  const t=await (await fetch('https://dev.avesa.lt/?ps_kat_deploy=D675x&k=ps2026&cb='+Date.now(),{headers:{'User-Agent':'Mozilla/5.0'}})).text();
  try{out.deploy=JSON.parse(t);}catch(e){out.deploy_raw=t.slice(0,900);}
  await fetch(BASE+'/'+idD,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})});
}catch(e){out.errors.push({s:'deploy',e:String(e)});}
// auth
let ck=null,idA=null;
try{
  idA=await snip('TEMP Auth Cookie (S675)', A);
  await new Promise(x=>setTimeout(x,3000));
  ck=JSON.parse(await (await fetch('https://dev.avesa.lt/?ps_auth649=A649x&k=ps2026&cb='+Date.now(),{headers:{'User-Agent':'Mozilla/5.0'}})).text());
}catch(e){out.errors.push({s:'auth',e:String(e)});}
if(ck&&ck.auth_ck){
 try{
  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({viewport:{width:1600,height:1050},ignoreHTTPSErrors:true});
  await ctx.addCookies([
    {name:ck.log_vardas,value:ck.log_ck,domain:'dev.avesa.lt',path:'/',httpOnly:true,secure:true},
    {name:ck.auth_vardas,value:ck.auth_ck,domain:'dev.avesa.lt',path:'/',httpOnly:true,secure:true},
    {name:ck.auth_vardas,value:ck.auth_ck,domain:'dev.avesa.lt',path:'/wp-admin',httpOnly:true,secure:true}]);
  const pg=await ctx.newPage();
  const errs=[]; pg.on('pageerror',e=>errs.push(String(e)));
  pg.on('dialog',d=>d.accept());
  // AV prekes su likuciu
  await pg.goto('https://dev.avesa.lt/wp-admin/admin.php?page=ps-katalogas&atnaujinti=1&sand=av&likutis=av_turi&per=50',{waitUntil:'domcontentloaded',timeout:150000});
  await pg.waitForTimeout(2500);
  out.pries=await pg.evaluate(()=>({
    langeliu:document.querySelectorAll('td.av-lang').length,
    mygtukas:!!document.getElementById('red-ijungti'),
    pirmos:Array.from(document.querySelectorAll('td.av-lang')).slice(0,4).map(td=>({id:td.dataset.id,buvo:td.dataset.buvo}))}));
  // ijungiam rezima
  await pg.click('#red-ijungti'); await pg.waitForTimeout(600);
  out.rezimas=await pg.evaluate(()=>({vidus:!document.querySelector('.red-vidus').hidden,
    klase:document.body.classList.contains('red-rezimas')}));
  // ivedam i pirmas tris: nustatyti, prideti, atimti
  const testai=[];
  const AV=await pg.$$('td[data-st="av"]');
  for(let i=0;i<2;i++){
    const td=AV[i];
    const inf=await td.evaluate(e=>({st:'av',id:e.dataset.id,buvo:e.dataset.buvo}));
    await td.click(); await pg.waitForTimeout(200);
    const v = i===0 ? '77' : '+5';
    await pg.keyboard.type(v); await pg.keyboard.press('Enter'); await pg.waitForTimeout(250);
    testai.push({...inf, ivestis:v});
  }
  await pg.keyboard.press('Escape'); await pg.waitForTimeout(200);
  const KN=await pg.$$('td[data-st="kaina"]');
  for(let i=0;i<2;i++){
    const td=KN[i];
    const inf=await td.evaluate(e=>({st:'kaina',id:e.dataset.id,buvo:e.dataset.buvo,cost:e.dataset.cost,lock:e.dataset.lock}));
    await td.click(); await pg.waitForTimeout(200);
    const v = i===0 ? '12,99' : '+1,50';
    await pg.keyboard.type(v); await pg.keyboard.press('Enter'); await pg.waitForTimeout(250);
    testai.push({...inf, ivestis:v});
  }
  await pg.keyboard.press('Escape'); await pg.waitForTimeout(300);
  out.ivesta=testai;
  out.po_ivedimo=await pg.evaluate(()=>({
    pakeista:document.querySelectorAll('td.red-lang.pakeista').length,
    persp:document.querySelectorAll('td.red-lang.persp').length,
    detalus:(document.getElementById('sg-detalus')||{}).textContent,
    kiek:(document.getElementById('sg-kiek')||{}).textContent,
    juosta:!document.getElementById('pskat-saugoti').hidden,
    rodo:Array.from(document.querySelectorAll('td.red-lang.pakeista')).map(e=>e.dataset.st+': '+e.textContent.trim().replace(/\s+/g,' '))}));
  await putFile('screenshots/s675_ivedimas.png', await pg.screenshot(), 'S675 ivedimas');
  // saugom
  await pg.click('#sg-saugoti'); await pg.waitForTimeout(4000);
  out.po_saugojimo=await pg.evaluate(()=>{
    const p=document.querySelector('.pskat-praneš');
    return {pranesimas:p?p.textContent.trim().replace(/\s+/g,' ').slice(0,220):null,
      pakeista_liko:document.querySelectorAll('td.red-lang.pakeista').length};
  });
  await putFile('screenshots/s675_issaugota.png', await pg.screenshot(), 'S675 issaugota');
  out.js=errs;
  await br.close();
 }catch(e){out.errors.push({s:'ui',e:String(e)});}
}
if(idA) await fetch(BASE+'/'+idA,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})});
try{
  const r=await fetch('https://dev.avesa.lt/parduotuve/?cb='+Date.now(),{headers:{'User-Agent':'Mozilla/5.0'}});
  const t=await r.text(); out.sveikata={http:r.status,len:t.length,fatal:/Fatal error/i.test(t)};
}catch(e){out.errors.push({s:'sv',e:String(e)});}
await putResult('s675_v1.json',out);
console.log('DONE');
